type I18nContextValue = { language: Language; setLanguage: (language: Language) => void; t: (key: string, values?: Record<string, string | number>) => string; localize: (value: string) => string }
const I18nContext = createContext<I18nContextValue | null>(null)

function interpolate(value: string, values?: Record<string, string | number>) {
  if (!values) return value
  return Object.entries(values).reduce((result, [key, replacement]) => result.replaceAll(`{${key}}`, String(replacement)), value)
}

export function I18nProvider({ children }: { children: ReactNode }) {
  const [language, setLanguageState] = useState<Language>(() => {
    const saved = localStore.getItem('nagarseva-language')
    return saved === 'hi' || saved === 'mr' ? saved : 'en'
  })
  const setLanguage = (next: Language) => { setLanguageState(next); localStore.setItem('nagarseva-language', next) }
  useEffect(() => {
    document.documentElement.lang = language
    document.title = dictionaries[language].pageTitle
    document.querySelector('meta[name="description"]')?.setAttribute('content', dictionaries[language].metaDescription)
  }, [language])
  const value = useMemo<I18nContextValue>(() => ({
    language,
    setLanguage,
    t: (key, values) => interpolate(dictionaries[language][key] ?? dictionaries.en[key] ?? key, values),
    localize: value => dictionaries[language][value] ?? value,
  }), [language])
  return <I18nContext.Provider value={value}>{children}</I18nContext.Provider>
}

export function useI18n() {
  const value = useContext(I18nContext)
  if (!value) throw new Error('useI18n must be used inside I18nProvider')
  return value
}
